Ui.Script:
-- Set here rather than by Localization.lua's LocalizeFrames — see the header.
TwentyFourHourTime = 1;

-- The reference's own thresholds, in minutes since midnight (game time), and its own
-- global names: an addon that wants to know when night falls reads exactly these.
GAMETIME_DAWN = ( 5 * 60) + 30;		-- 5:30 AM
GAMETIME_DUSK = (21 * 60) +  0;		-- 9:00 PM

-- UI-TOD-Indicator is one 128x64 sheet carrying two 50-px icons side by side: the sun at
-- u=0, the moon exactly half a sheet to its right. So the whole day/night decision is
-- which of the two u origins the 50-px window sits on.
local TOD_ICON_WIDTH = 50/128;
local TOD_ICON_HEIGHT = 50/64;
local TOD_NIGHT_ORIGIN = 0.5;

function GameTimeFrame_Update()
    local hour, minute = GetGameTime();
    local minuteOfDay = (hour * 60) + minute;
    -- OnUpdate calls this every frame; only a changed game MINUTE is worth any work.
    if minuteOfDay == this.timeOfDay then
        return;
    end
    this.timeOfDay = minuteOfDay;

    local origin = 0;
    if minuteOfDay < GAMETIME_DAWN or minuteOfDay >= GAMETIME_DUSK then
        origin = TOD_NIGHT_ORIGIN;
    end
    GameTimeTexture:SetTexCoord(origin, origin + TOD_ICON_WIDTH, 0, TOD_ICON_HEIGHT);

    -- A tooltip we still own is showing last minute's clock; re-word it in place.
    if GameTooltip:IsOwned(this) then
        GameTimeFrame_UpdateTooltip(hour, minute);
    end
end

-- The one clock formatter, since the tooltip and the getter below want the same string in
-- two different wrappers. TwentyFourHourTime picks the plain HH:MM form; otherwise the
-- hour folds into 1..12 (midnight and noon both being 12) and the AM/PM half is carried by
-- which format string is used, not by any text this file spells out.
local function clockText(hour, minute)
    if TwentyFourHourTime then
        return format(TIME_TWENTYFOURHOURS, hour, minute);
    end
    local afternoon = (hour >= 12);
    if hour > 12 then
        hour = hour - 12;
    elseif hour == 0 then
        hour = 12;
    end
    if afternoon then
        return format(TIME_TWELVEHOURPM, hour, minute);
    end
    return format(TIME_TWELVEHOURAM, hour, minute);
end

function GameTimeFrame_UpdateTooltip(hours, minutes)
    GameTooltip:SetText(clockText(hours, minutes));
end

function GameTime_GetTime()
    return clockText(GetGameTime());
end
